"""Human-authored CPC9 questions; formats catalogue facts, never scores meaning.

This auditor has no import path to participant modules and is never imported by
them. A produced plan is a set of testable questions, not positive evidence.
"""
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
CATALOGUE = ROOT / 'referencias/NSM65_CATALOGO_4_5.json'

