def main():
    catalogue = json.loads(CATALOGUE.read_text(encoding='utf8'))
    assert len(catalogue['entries']) == 65
    assert {e['glosa_inglesa_id'] for e in catalogue['entries']} == set(QUESTIONS)
    source_sha = hashlib.sha256(CATALOGUE.read_bytes()).hexdigest()
    entries = []
    for original in catalogue['entries']:
        gloss = original['glosa_inglesa_id']
        question, mechanism, contrasts, limitation = QUESTIONS[gloss]
        entries.append({
            'id': original['id'], 'forma_es': original['forma_es'], 'grupo': original['grupo_documental'],
            'glosa_fuente': gloss, 'forma_fuente': original['forma_fuente'],
            'variantes_documentadas': original['variantes_documentadas'], 'fuentes_linguisticas': original['fuentes'],
            'catalogue_sha256': source_sha, 'funcion_a_investigar': question,
            'relacion_nativa_candidata': mechanism, 'experiencias_y_controles': contrasts,
            'observables': ['Entradas admitidas/rechazadas exactas', 'Encuentros y campos físicos locales',
                            'Función posterior bajo criterio fijado', 'Retención y nueva adquisición',
                            'Efecto de corte selectivo y sham'],
            'senal': 'Forma arbitraria fijada en receta; nunca el nombre humano como target ni clasificación resuelta.',
            'composicion': 'Probar componentes enseñados por separado, combinación nueva y retirada selectiva; no inferir del texto.',
            'reserva': 'Variar un factor pertinente de la lista individual después de congelar preparación/lector; conservar el intento si falla.',
            'retencion': 'Nueva consulta después de otra adquisición, primera respuesta separada de posteriores y sin reenseñanza oculta.',
            'comunicacion': 'Emisión dependiente de experiencia, transporte en mismoRuntime y uso posterior del receptor; inversión de rol sólo si se ejecuta.',
            'dependencias': limitation,
            'dimensiones_A_J': {name: {'estado': 'PENDIENTE_DE_ADJUDICACION_CPC9', 'evidencia': []}
                for name in ('A_experiencia_causal', 'B_relacion_adquirida', 'C_funcion_posterior', 'D_forma_adquirida',
                             'E_retencion', 'F_generalizacion', 'G_composicion', 'H_comunicacion',
                             'I_E1_continuo', 'J_aporte_externo')},
            'estado_inicial_CPC9': 'Pregunta operacional, no afirmación positiva ni copia de estadosE0 anteriores',
            'limitacion_y_evidencia_faltante': limitation,
            'equivalencia_con_significado_humano_completo_demostrada': False
        })
    document = {'schema': 'CPC9.NSM65.individual_questions.v1', 'count': 65,
        'catalogue': {'path': 'referencias/NSM65_CATALOGO_4_5.json', 'sha256': source_sha,
                      'version': catalogue['catalogue_version'], 'sources': catalogue['sources']},
        'method': 'Human-authored operational questions and candidate mechanisms. This auditor never supplies answers to an organism. All positive dimensions require separate primary evidence; historical andnew lives are distinct.',
        'entries': entries}
    output = ROOT / 'revision/NSM65_PLAN_CPC9.json'
    output.write_text(json.dumps(document, ensure_ascii=False, indent=2)+'\n', encoding='utf8')
    print(json.dumps({'path': str(output), 'entries': len(entries), 'sha256': hashlib.sha256(output.read_bytes()).hexdigest()}))


if __name__ == '__main__':
    main()
